api-tugas/penyimpanan.js<pre><code>export class PenyimpananTugas {
  #tugas = [];
  #idBerikut = 1;

  semua({ selesai } = {}) {
    if (selesai === undefined) {
      return [...this.#tugas];
    }
    return this.#tugas.filter((t) =&gt; t.selesai === selesai);
  }

  cari(id) {
    const tugas = this.#tugas.find((t) =&gt; t.id === id);
    if (tugas === undefined) {
      return undefined;
    }
    return { ...tugas };
  }

  tambah(judul) {
    const baru = { id: this.#idBerikut++, judul, selesai: false };
    this.#tugas.push(baru);
    return { ...baru };
  }

  ubah(id, perubahan) {
    const indeks = this.#tugas.findIndex((t) =&gt; t.id === id);
    if (indeks === -1) {
      return undefined;
    }
    this.#tugas[indeks] = { ...this.#tugas[indeks], ...perubahan };
    return { ...this.#tugas[indeks] };
  }

  hapus(id) {
    const indeks = this.#tugas.findIndex((t) =&gt; t.id === id);
    if (indeks === -1) {
      return false;
    }
    this.#tugas.splice(indeks, 1);
    return true;
  }
}
</code></pre> <p>Beberapa keputusan yang disengaja:</p> <ul> <li>Data disimpan di field privat <code>#tugas</code> (bab 13), sehingga tidak bisa diubah dari luar.</li> <li>Method mengembalikan salinan (<code>{ ...tugas }</code>), bukan objek aslinya. Kalau tidak, kode lain yang mengubah hasilnya akan diam-diam mengubah data di dalam penyimpanan. Salah satu tes nanti membuktikan hal ini.</li> <li>Penyimpanan tidak melempar error HTTP. Ia mengembalikan <code>undefined</code> atau <code>false</code> untuk "tidak ada", dan lapis rute yang menentukan itu <code>404</code>.</li> </ul>

api-tugas/validasi.js<pre><code>import { GalatHttp } from "./galat.js";

export function validasiId(teks) {
  const id = Number(teks);
  if (!Number.isInteger(id) || id &lt; 1) {
    throw new GalatHttp(400, "id harus bilangan bulat positif");
  }
  return id;
}

export function validasiJudul(judul) {
  if (typeof judul !== "string" || judul.trim() === "") {
    throw new GalatHttp(400, "judul wajib diisi");
  }
  if (judul.trim().length &gt; 100) {
    throw new GalatHttp(400, "judul maksimal 100 karakter");
  }
  return judul.trim();
}

export function validasiSelesai(nilai) {
  if (typeof nilai !== "boolean") {
    throw new GalatHttp(400, "selesai harus true atau false");
  }
  return nilai;
}
</code></pre> <p>Setiap fungsi validasi memeriksa satu hal, melempar <code>GalatHttp(400, ...)</code> jika salah, dan mengembalikan nilai yang sudah bersih (misalnya judul tanpa spasi di tepi).</p>

api-tugas/tugas.js<pre><code>import { Router } from "express";
import { GalatHttp } from "./galat.js";
import { validasiId, validasiJudul, validasiSelesai } from "./validasi.js";

export function buatRuteTugas(penyimpanan) {
  const rute = Router();

  function ambilAtau404(teksId) {
    const id = validasiId(teksId);
    const tugas = penyimpanan.cari(id);
    if (tugas === undefined) {
      throw new GalatHttp(404, `Tugas ${id} tidak ditemukan`);
    }
    return tugas;
  }

  rute.get("/", (req, res) =&gt; {
    const { selesai, halaman = "1", batas = "10" } = req.query;

    let saringan;
    if (selesai !== undefined) {
      if (selesai !== "true" &amp;&amp; selesai !== "false") {
        throw new GalatHttp(400, "selesai harus true atau false");
      }
      saringan = { selesai: selesai === "true" };
    }

    const nomorHalaman = Number(halaman);
    const ukuran = Number(batas);
    if (!Number.isInteger(nomorHalaman) || nomorHalaman &lt; 1) {
      throw new GalatHttp(400, "halaman harus bilangan bulat positif");
    }
    if (!Number.isInteger(ukuran) || ukuran &lt; 1 || ukuran &gt; 50) {
      throw new GalatHttp(400, "batas harus antara 1 dan 50");
    }

    const semua = penyimpanan.semua(saringan);
    const awal = (nomorHalaman - 1) * ukuran;
    res.json({
      data: semua.slice(awal, awal + ukuran),
      halaman: nomorHalaman,
      batas: ukuran,
      total: semua.length,
    });
  });

  rute.post("/", (req, res) =&gt; {
    const judul = validasiJudul(req.body?.judul);
    const baru = penyimpanan.tambah(judul);
    res.status(201).location(`/api/tugas/${baru.id}`).json(baru);
  });

  rute.get("/:id", (req, res) =&gt; {
    res.json(ambilAtau404(req.params.id));
  });

  rute.put("/:id", (req, res) =&gt; {
    const tugas = ambilAtau404(req.params.id);
    const judul = validasiJudul(req.body?.judul);
    const selesai = validasiSelesai(req.body?.selesai);
    res.json(penyimpanan.ubah(tugas.id, { judul, selesai }));
  });

  rute.patch("/:id", (req, res) =&gt; {
    const tugas = ambilAtau404(req.params.id);
    const { judul, selesai } = req.body || {};
    const perubahan = {};
    if (judul !== undefined) {
      perubahan.judul = validasiJudul(judul);
    }
    if (selesai !== undefined) {
      perubahan.selesai = validasiSelesai(selesai);
    }
    if (Object.keys(perubahan).length === 0) {
      throw new GalatHttp(400, "tidak ada yang diubah");
    }
    res.json(penyimpanan.ubah(tugas.id, perubahan));
  });

  rute.delete("/:id", (req, res) =&gt; {
    const tugas = ambilAtau404(req.params.id);
    penyimpanan.hapus(tugas.id);
    res.sendStatus(204);
  });

  return rute;
}
</code></pre> <p>Bagian-bagian yang patut diperhatikan:</p> Bagian Penjelasan <code>buatRuteTugas(penyimpanan)</code> Fungsi yang menerima penyimpanan lalu membuat Router. Rute tidak membuat penyimpanannya sendiri <code>ambilAtau404</code> Fungsi bantu yang memvalidasi id, mengambil tugas, dan melempar 404. Dipakai di empat rute agar tidak berulang <code>const { selesai, halaman = "1", batas = "10" } = req.query</code> Destructuring dengan nilai bawaan (bab 9). Karena <code>req.query</code> selalu berisi teks, nilai bawaannya juga teks Paginasi <code>awal = (halaman - 1) * ukuran</code>, lalu <code>slice(awal, awal + ukuran)</code> mengambil satu halaman <code>req.body?.judul</code> <code>?.</code> mencegah <code>TypeError</code> jika klien tidak mengirim body sama sekali (<code>req.body</code> bernilai <code>undefined</code>) <code>PUT</code> Mewajibkan kedua field, <code>judul</code> dan <code>selesai</code> <code>PATCH</code> Memvalidasi hanya field yang ada, dan menolak jika tidak ada satu pun field yang dikirim <code>res.sendStatus(204)</code> Berhasil tanpa isi

api-tugas/app.js<pre><code>import express from "express";
import { GalatHttp } from "./galat.js";
import { PenyimpananTugas } from "./penyimpanan.js";
import { buatRuteTugas } from "./tugas.js";

export function buatApp(penyimpanan = new PenyimpananTugas()) {
  const app = express();
  app.disable("x-powered-by");

  app.use(express.json());
  app.use("/api/tugas", buatRuteTugas(penyimpanan));

  app.use((req, res) =&gt; {
    throw new GalatHttp(404, "Jalur tidak ditemukan");
  });

  app.use((error, req, res, next) =&gt; {
    if (error.type === "entity.parse.failed") {
      return res.status(400).json({ galat: "JSON tidak valid" });
    }
    if (error.type === "entity.too.large") {
      return res.status(413).json({ galat: "Body terlalu besar" });
    }
    if (error instanceof GalatHttp) {
      return res.status(error.status).json({ galat: error.message });
    }
    console.error(error);
    res.status(500).json({ galat: "Kesalahan server" });
  });

  return app;
}
</code></pre> api-tugas/server.js<pre><code>import { buatApp } from "./app.js";

